def decimal_to_binary(decimal):
    if not isinstance(decimal, int) or decimal < 0:
        raise ValueError("Input must be a non-negative integer")

    if decimal == 0:
        return "db0db"

    binary_str = bin(decimal)[2:]
    return f"db{binary_str}db"

